UPDATE place_availability
SET status = 'RESERVED'
WHERE place_id = #{placeId}
AND status = 'OPEN'
AND start_at >= #{startAt}
AND end_at <= #{endAt}

mapper.select:
SELECT id
FROM place_availability
WHERE place_id = #{placeId}
AND start_at >= #{startAt}
AND end_at <= #{endAt}
ORDER BY start_at ASC

SELECT
id AS slotId,
start_at AS startAt,
end_at AS endAt,
status
FROM place_availability
WHERE place_id = #{placeId}
AND start_at >= #{fromAt}
AND start_at < #{toAt}
ORDER BY start_at ASC

SELECT COUNT(*)
FROM place_availability
WHERE place_id = #{placeId}
AND status = 'OPEN'
AND start_at >= #{startAt}
AND end_at <= #{endAt}

mapper.update:
UPDATE place_availability
SET status = #{status}
WHERE id = #{slotId}
AND place_id = #{placeId}
AND status <> 'RESERVED'
